pragma solidity ^0.8.13;

interface IEntropy {
    function getDefaultProvider() external view returns (address);
    function request(address provider, bytes32 userCommitment, bool useBlockHash) external payable returns (uint64);
    function getFee(address provider) external view returns (uint256);
}

interface IEntropyConsumer {
    function entropyCallback(uint64 sequenceNumber, address provider, bytes32 randomNumber) external;
}

contract CoinFlip is IEntropyConsumer {
    IEntropy public immutable entropy;
    address public immutable entropyProvider;

    struct Bet {
        address player;
        uint256 amount;
        bool prediction; // true for heads, false for tails
        bool fulfilled;
        bool won;
    }

    mapping(uint64 => Bet) public bets;
    mapping(address => uint256) public playerWinnings;

    event BetPlaced(address indexed player, uint64 sequenceNumber, uint256 amount, bool prediction);
    event BetResolved(address indexed player, uint64 sequenceNumber, bool result, bool won, uint256 payout);
    event WinningsClaimed(address indexed player, uint256 amount);

    constructor(address _entropy) {
        entropy = IEntropy(_entropy);
        entropyProvider = entropy.getDefaultProvider();
    }

    function flipCoin(bool _prediction, bytes32 _userCommitment) external payable {
        require(msg.value > 0, "Bet amount must be greater than 0");
        require(address(this).balance >= msg.value * 2, "Insufficient contract balance");

        uint256 fee = entropy.getFee(entropyProvider);
        require(msg.value > fee, "Bet must cover entropy fee");

        uint256 betAmount = msg.value - fee;
        uint64 sequenceNumber = entropy.request{value: fee}(entropyProvider, _userCommitment, true);

        bets[sequenceNumber] = Bet({
            player: msg.sender,
            amount: betAmount,
            prediction: _prediction,
            fulfilled: false,
            won: false
        });

        emit BetPlaced(msg.sender, sequenceNumber, betAmount, _prediction);
    }

    function entropyCallback(uint64 sequenceNumber, address, bytes32 randomNumber) external override {
        require(msg.sender == address(entropy), "Only entropy contract can call this");

        Bet storage bet = bets[sequenceNumber];
        require(!bet.fulfilled, "Bet already fulfilled");
        require(bet.player != address(0), "Invalid bet");

        // Extract coin flip result from random number (even = heads, odd = tails)
        bool result = uint256(randomNumber) % 2 == 0; // true = heads, false = tails

        bet.fulfilled = true;
        bet.won = (result == bet.prediction);

        if (bet.won) {
            playerWinnings[bet.player] += bet.amount * 2;
            emit BetResolved(bet.player, sequenceNumber, result, true, bet.amount * 2);
        } else {
            emit BetResolved(bet.player, sequenceNumber, result, false, 0);
        }
    }

    function claimWinnings() external {
        uint256 winnings = playerWinnings[msg.sender];
        require(winnings > 0, "No winnings to claim");

        playerWinnings[msg.sender] = 0;
        payable(msg.sender).transfer(winnings);

        emit WinningsClaimed(msg.sender, winnings);
    }

    // Owner functions
    function fundContract() external payable {}

    function withdraw(uint256 amount) external {
        // Simple owner check - in production, use proper access control
        require(msg.sender == address(0x1234567890123456789012345678901234567890), "Only owner");
        payable(msg.sender).transfer(amount);
    }

    function getContractBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function getBet(uint64 sequenceNumber) external view returns (Bet memory) {
        return bets[sequenceNumber];
    }
}"}

