{"path": "src/CoinFlip.sol", "content": "// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

interface IEntropy {
    function getDefaultProvider() external view returns (address);
    function request(address provider, bytes32 userCommitment, bool useBlockHash) external payable returns (uint64);
    function getFee(address provider) external view returns (uint256);
}

interface IEntropyConsumer {
    function entropyCallback(uint64 sequenceNumber, address provider, bytes32 randomNumber) external;
}

contract CoinFlip is IEntropyConsumer {
    IEntropy public immutable entropy;
    address public immutable entropyProvider;

    struct Bet {
        address player;
        uint256 amount;
        bool prediction; // true for heads, false for tails
        bool fulfilled;
        bool won;
    }

    mapping(uint64 => Bet) public bets;
    mapping(address => uint256) public playerWinnings;

    event BetPlaced(address indexed player, uint64 sequenceNumber, uint256 amount, bool prediction);
    event BetResolved(address indexed player, uint64 sequenceNumber, bool result, bool won, uint256 payout);
    event WinningsClaimed(address indexed player, uint256 amount);

    constructor(address _entropy) {
        entropy = IEntropy(_entropy);
        entropyProvider = entropy.getDefaultProvider();
    }

    function flipCoin(bool _prediction, bytes32 _userCommitment) external payable {
        require(msg.value > 0, "Bet amount must be greater than 0");
        require(address(this).balance >= msg.value * 2, "Insufficient contract balance");

        uint256 fee = entropy.getFee(entropyProvider);
        require(msg.value > fee, "Bet must cover entropy fee");

        uint256 betAmount = msg.value - fee;
        uint64 sequenceNumber = entropy.request{value: fee}(entropyProvider, _userCommitment, true);

        bets[sequenceNumber] = Bet({
            player: msg.sender,
            amount: betAmount,
            prediction: _prediction,
            fulfilled: false,
            won: false
        });

        emit BetPlaced(msg.sender, sequenceNumber, betAmount, _prediction);
    }

    function entropyCallback(uint64 sequenceNumber, address, bytes32 randomNumber) external override {
        require(msg.sender == address(entropy), "Only entropy contract can call this");

        Bet storage bet = bets[sequenceNumber];
        require(!bet.fulfilled, "Bet already fulfilled");
        require(bet.player != address(0), "Invalid bet");

        // Extract coin flip result from random number (even = heads, odd = tails)
        bool result = uint256(randomNumber) % 2 == 0; // true = heads, false = tails

        bet.fulfilled = true;
        bet.won = (result == bet.prediction);

        if (bet.won) {
            playerWinnings[bet.player] += bet.amount * 2;
            emit BetResolved(bet.player, sequenceNumber, result, true, bet.amount * 2);
        } else {
            emit BetResolved(bet.player, sequenceNumber, result, false, 0);
        }
    }

    function claimWinnings() external {
        uint256 winnings = playerWinnings[msg.sender];
        require(winnings > 0, "No winnings to claim");

        playerWinnings[msg.sender] = 0;
        payable(msg.sender).transfer(winnings);

        emit WinningsClaimed(msg.sender, winnings);
    }

    // Owner functions
    function fundContract() external payable {}

    function withdraw(uint256 amount) external {
        // Simple owner check - in production, use proper access control
        require(msg.sender == address(0x1234567890123456789012345678901234567890), "Only owner");
        payable(msg.sender).transfer(amount);
    }

    function getContractBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function getBet(uint64 sequenceNumber) external view returns (Bet memory) {
        return bets[sequenceNumber];
    }
}"}

{"path": "frontend/src/App.jsx", "content": "import { useState, useEffect } from 'react'
import { ethers } from 'ethers'
import './App.css'

// Contract ABI (simplified for the main functions we need)
const CONTRACT_ABI = [
  "function flipCoin(bool _prediction, bytes32 _userCommitment) external payable",
  "function claimWinnings() external",
  "function playerWinnings(address) external view returns (uint256)",
  "function getBet(uint64) external view returns (tuple(address player, uint256 amount, bool prediction, bool fulfilled, bool won))",
  "function getContractBalance() external view returns (uint256)",
  "event BetPlaced(address indexed player, uint64 sequenceNumber, uint256 amount, bool prediction)",
  "event BetResolved(address indexed player, uint64 sequenceNumber, bool result, bool won, uint256 payout)"
]

// You'll need to deploy the contract and update this address
const CONTRACT_ADDRESS = "0x..." // Update after deployment

function App() {
  const [provider, setProvider] = useState(null)
  const [signer, setSigner] = useState(null)
  const [contract, setContract] = useState(null)
  const [account, setAccount] = useState('')
  const [betAmount, setBetAmount] = useState('0.01')
  const [prediction, setPrediction] = useState(true) // true for heads
  const [winnings, setWinnings] = useState('0')
  const [loading, setLoading] = useState(false)
  const [recentBets, setRecentBets] = useState([])

  useEffect(() => {
    if (window.ethereum) {
      const web3Provider = new ethers.BrowserProvider(window.ethereum)
      setProvider(web3Provider)
    }
  }, [])

  const connectWallet = async () => {
    if (!provider) {
      alert('Please install MetaMask!')
      return
    }

    try {
      await provider.send("eth_requestAccounts", [])
      const signer = await provider.getSigner()
      const address = await signer.getAddress()

      setSigner(signer)
      setAccount(address)

      if (CONTRACT_ADDRESS !== "0x...") {
        const contractInstance = new ethers.Contract(CONTRACT_ADDRESS, CONTRACT_ABI, signer)
        setContract(contractInstance)

        // Load winnings
        const userWinnings = await contractInstance.playerWinnings(address)
        setWinnings(ethers.formatEther(userWinnings))
      }

      // Switch to Base Sepolia
      try {
        await window.ethereum.request({
          method: 'wallet_switchEthereumChain',
          params: [{ chainId: '0x14A34' }], // Base Sepolia
        })
      } catch (error) {
        // Add Base Sepolia if not added
        if (error.code === 4902) {
          await window.ethereum.request({
            method: 'wallet_addEthereumChain',
            params: [{
              chainId: '0x14A34',
              chainName: 'Base Sepolia',
              nativeCurrency: { name: 'ETH', symbol: 'ETH', decimals: 18 },
              rpcUrls: ['https://sepolia.base.org'],
              blockExplorerUrls: ['https://sepolia-explorer.base.org/']
            }]
          })
        }
      }
    } catch (error) {
      console.error('Error connecting wallet:', error)
    }
  }

  const flipCoin = async () => {
    if (!contract) return

    setLoading(true)
    try {
      // Generate random user commitment
      const userCommitment = ethers.randomBytes(32)

      // Add entropy fee (approximately 0.001 ETH)
      const betAmountWei = ethers.parseEther(betAmount)
      const entropyFee = ethers.parseEther("0.001")
      const totalValue = betAmountWei + entropyFee

      const tx = await contract.flipCoin(prediction, userCommitment, {
        value: totalValue
      })

      console.log('Transaction sent:', tx.hash)
      await tx.wait()

      alert(`Coin flip submitted! Transaction: ${tx.hash}`)

    } catch (error) {
      console.error('Error flipping coin:', error)
      alert('Error flipping coin: ' + error.message)
    }
    setLoading(false)
  }

  const claimWinnings = async () => {
    if (!contract) return

    try {
      const tx = await contract.claimWinnings()
      await tx.wait()

      alert('Winnings claimed!')
      setWinnings('0')
    } catch (error) {
      console.error('Error claiming winnings:', error)
      alert('Error claiming winnings: ' + error.message)
    }
  }

  return (
    <div className="App">
      <h1>🪙 Coin Flip Game</h1>
      <p>Powered by Pyth Entropy on Base Sepolia</p>

      {!account ? (
        <button onClick={connectWallet} className="connect-btn">
          Connect Wallet
        </button>
      ) : (
        <div>
          <p>Connected: {account.slice(0, 6)}...{account.slice(-4)}</p>

          {CONTRACT_ADDRESS === "0x..." ? (
            <div className="deploy-notice">
              <h2>⚠️ Contract Not Deployed</h2>
              <p>Please deploy the CoinFlip contract to Base Sepolia and update CONTRACT_ADDRESS in App.jsx</p>
              <p>Contract source: src/CoinFlip.sol</p>
              <p>Constructor arg: 0x4821932D0CDd71225A6d914706A621e0389D7061 (Pyth Entropy)</p>
            </div>
          ) : (
            <div>
              <div className="game-section">
                <h2>Place Your Bet</h2>
                <div className="bet-controls">
                  <input
                    type="number"
                    step="0.001"
                    min="0.001"
                    value={betAmount}
                    onChange={(e) => setBetAmount(e.target.value)}
                    placeholder="Bet amount (ETH)"
                  />
                  <div className="prediction-buttons">
                    <button 
                      className={prediction ? 'active' : ''}
                      onClick={() => setPrediction(true)}
                    >
                      🌟 Heads
                    </button>
                    <button 
                      className={!prediction ? 'active' : ''}
                      onClick={() => setPrediction(false)}
                    >
                      🔥 Tails
                    </button>
                  </div>
                  <button 
                    onClick={flipCoin} 
                    disabled={loading}
                    className="flip-btn"
                  >
                    {loading ? 'Flipping...' : 'Flip Coin!'}
                  </button>
                </div>
              </div>

              {winnings !== '0' && (
                <div className="winnings-section">
                  <h3>💰 Winnings Available: {winnings} ETH</h3>
                  <button onClick={claimWinnings}>Claim Winnings</button>
                </div>
              )}

              <div className="info">
                <p>• Win 2x your bet amount</p>
                <p>• Small fee required for verifiable randomness</p>
                <p>• Results are provably fair via Pyth Entropy</p>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

export default App"}

