.App {
  max-width: 800px;
  margin: 0 auto;
  padding: 2rem;
  text-align: center;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  color: white;
}

.connect-btn, .flip-btn {
  background: #4CAF50;
  color: white;
  border: none;
  padding: 12px 24px;
  font-size: 18px;
  border-radius: 8px;
  cursor: pointer;
  margin: 10px;
  transition: all 0.3s ease;
}

.connect-btn:hover, .flip-btn:hover {
  background: #45a049;
  transform: scale(1.05);
}

.flip-btn:disabled {
  background: #cccccc;
  cursor: not-allowed;
  transform: none;
}

.game-section {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border-radius: 16px;
  padding: 2rem;
  margin: 2rem 0;
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.bet-controls {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  align-items: center;
}

.bet-controls input {
  padding: 12px;
  font-size: 16px;
  border: none;
  border-radius: 8px;
  width: 200px;
  text-align: center;
}

.prediction-buttons {
  display: flex;
  gap: 1rem;
}

.prediction-buttons button {
  background: rgba(255, 255, 255, 0.2);
  color: white;
  border: 2px solid transparent;
  padding: 16px 24px;
  font-size: 18px;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.3s ease;
  min-width: 120px;
}

.prediction-buttons button:hover {
  background: rgba(255, 255, 255, 0.3);
  transform: scale(1.05);
}

.prediction-buttons button.active {
  background: #FF6B6B;
  border-color: #FF6B6B;
  box-shadow: 0 0 20px rgba(255, 107, 107, 0.5);
}

.winnings-section {
  background: rgba(76, 175, 80, 0.2);
  border: 2px solid #4CAF50;
  border-radius: 12px;
  padding: 1.5rem;
  margin: 1rem 0;
}

.winnings-section button {
  background: #4CAF50;
  color: white;
  border: none;
