        <button onClick={connectWallet} className="connect-btn">
          Connect Wallet
        </button>
      ) : (
        <div>
          <p>Connected: {account.slice(0, 6)}...{account.slice(-4)}</p>

          {CONTRACT_ADDRESS === "0x..." ? (
            <div className="deploy-notice">
              <h2>⚠️ Contract Not Deployed</h2>
              <p>Please deploy the CoinFlip contract to Base Sepolia and update CONTRACT_ADDRESS in App.jsx</p>
              <p>Contract source: src/CoinFlip.sol</p>
              <p>Constructor arg: 0x4821932D0CDd71225A6d914706A621e0389D7061 (Pyth Entropy)</p>
            </div>
          ) : (
            <div>
              <div className="game-section">
                <h2>Place Your Bet</h2>
                <div className="bet-controls">
                  <input
                    type="number"
                    step="0.001"
                    min="0.001"
                    value={betAmount}
                    onChange={(e) => setBetAmount(e.target.value)}
                    placeholder="Bet amount (ETH)"
                  />
                  <div className="prediction-buttons">
                    <button 
                      className={prediction ? 'active' : ''}
                      onClick={() => setPrediction(true)}
                    >
                      🌟 Heads
                    </button>
                    <button 
                      className={!prediction ? 'active' : ''}
                      onClick={() => setPrediction(false)}
                    >
                      🔥 Tails
                    </button>
                  </div>
                  <button 
                    onClick={flipCoin} 
                    disabled={loading}
                    className="flip-btn"
                  >
                    {loading ? 'Flipping...' : 'Flip Coin!'}
                  </button>
                </div>
              </div>

              {winnings !== '0' && (
                <div className="winnings-section">
                  <h3>💰 Winnings Available: {winnings} ETH</h3>
                  <button onClick={claimWinnings}>Claim Winnings</button>
                </div>
              )}

              <div className="info">
                <p>• Win 2x your bet amount</p>
                <p>• Small fee required for verifiable randomness</p>
                <p>• Results are provably fair via Pyth Entropy</p>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )
}

export default App"}

